import assert from 'node:assert/strict';
import { test } from 'vitest';
import { activateCard, advanceGame, createGame, GAME_NAME_MAX_CHARACTERS } from './game.ts';
import { decodeSnapshot, encodeSnapshot, SNAPSHOT_KEYS, SNAPSHOT_MAX_BYTES } from './snapshot.ts';
import { isJsonObject } from './saved-format.ts';
import { EXAMPLE_CODE, EXAMPLE_PAIRS } from './game.fixture.ts';

function fields(name?: unknown): Record<string, unknown> {
  const value: unknown = JSON.parse(encodeSnapshot(createGame(EXAMPLE_CODE)));
  assert.ok(isJsonObject(value));
  return name === undefined ? value : { ...value, name };
}

test('named progress preserves literal text and pending time through unordered snapshots', () => {
  const name = '  Friday "pairs" — 星🌙 <b>play</b>  ';
  const state = advanceGame(activateCard(activateCard(createGame(EXAMPLE_CODE, name), 0), 1), 175);
  const text = encodeSnapshot(state);
  assert.deepEqual(decodeSnapshot(text), state);
  const value: unknown = JSON.parse(text);
  assert.ok(isJsonObject(value));
  assert.equal(value.name, name);
  const reordered = Object.fromEntries(Object.entries(value).reverse());
  assert.deepEqual(decodeSnapshot(JSON.stringify(reordered)), state);
});

test('unnamed exports keep the legacy fields and legacy imports receive an empty name', () => {
  const state = createGame(EXAMPLE_CODE);
  assert.equal(state.name, '');
  const value = fields();
  assert.deepEqual(Object.keys(value), SNAPSHOT_KEYS);
  assert.deepEqual(decodeSnapshot(JSON.stringify(value)), state);
  assert.deepEqual(decodeSnapshot(JSON.stringify(fields(''))), state);
});

test('names survive matching, elapsed time and completed snapshot loads', () => {
  let state = createGame(EXAMPLE_CODE, 'Weekend puzzle');
  for (const [first, second] of EXAMPLE_PAIRS)
    state = activateCard(advanceGame(activateCard(state, first), 10), second);
  assert.equal(state.name, 'Weekend puzzle');
  assert.deepEqual(decodeSnapshot(encodeSnapshot(state)), {
    ...state,
    matched: [...state.matched].sort((left, right) => left - right),
  });
});

test('name validation allows the input boundary and rejects invalid types and longer strings', () => {
  assert.ok(decodeSnapshot(JSON.stringify(fields('x'.repeat(GAME_NAME_MAX_CHARACTERS)))));
  assert.ok(decodeSnapshot(JSON.stringify(fields('🌙'.repeat(GAME_NAME_MAX_CHARACTERS / 2)))));
  for (const name of [null, true, 42, [], {}, 'x'.repeat(GAME_NAME_MAX_CHARACTERS + 1)])
    assert.equal(decodeSnapshot(JSON.stringify(fields(name))), null);
});

test('named snapshots require every progress field and reject extra metadata', () => {
  const named = fields('My game');
  for (const missing of SNAPSHOT_KEYS) {
    const remaining = Object.fromEntries(Object.entries(named).filter(([key]) => key !== missing));
    assert.equal(decodeSnapshot(JSON.stringify(remaining)), null);
    assert.equal(decodeSnapshot(JSON.stringify({ ...remaining, extra: true })), null);
  }
  assert.equal(decodeSnapshot(JSON.stringify({ ...named, extra: true })), null);
});

test('named snapshots retain the exact UTF-8 byte limit', () => {
  const text = JSON.stringify(fields('星'.repeat(GAME_NAME_MAX_CHARACTERS)));
  const padded = text + ' '.repeat(SNAPSHOT_MAX_BYTES - Buffer.byteLength(text));
  assert.equal(Buffer.byteLength(padded), SNAPSHOT_MAX_BYTES);
  assert.ok(decodeSnapshot(padded));
  assert.equal(decodeSnapshot(padded + ' '), null);
});

import { useRef, useState } from 'react';
import { createGame, isValidGameName } from '../game.ts';
import { parseBoardCode, isValidSize } from '../deck.ts';
import { decodeSnapshot, encodeSnapshot } from '../snapshot.ts';
import { freshBoardCode } from './fresh-board.ts';
import { activateSession, initialSession, replaceGame, SessionNotice } from './session.ts';
import { readPreferences } from './storage.ts';
import { browserStore, useSavedPreferences } from './use-saved-preferences.ts';
import { useSessionClock } from './use-session-clock.ts';
import type { Session } from './session.ts';

export function useGame() {
  const [store] = useState(browserStore);
  const [session, setSession] = useState(() => {
    const preferences = readPreferences(store);
    return initialSession(freshBoardCode(preferences.size), preferences);
  });
  const current = useRef(session);

  function commit(next: Session): void {
    if (next === current.current) return;
    current.current = next;
    setSession(next);
  }

  const clock = useSessionClock(session, current, commit);
  useSavedPreferences(store, session.preferences);

  function newGame(size = current.current.game.size): void {
    if (!isValidSize(size)) return;
    const next = createGame(freshBoardCode(size, current.current.game.seed));
    clock.reset();
    commit(replaceGame(current.current, next, false));
  }

  function restart(): void {
    const { boardCode, name } = current.current.game;
    clock.reset();
    commit(replaceGame(current.current, createGame(boardCode, name), false));
  }

  function rename(name: string): void {
    if (!isValidGameName(name) || name === current.current.game.name) return;
    commit({ ...current.current, game: { ...current.current.game, name } });
  }

  function notice(feedback: string): void {
    commit({
      ...current.current,
      feedback,
      loadNotice: feedback,
      announcement: current.current.announcement + 1,
    });
  }

  function loadBoard(code: string): boolean {
    code = code.trim();
    if (!parseBoardCode(code)) {
      notice(SessionNotice.invalidBoard);
      return false;
    }
    clock.reset();
    commit(replaceGame(current.current, createGame(code), false));
    return true;
  }

  function loadSnapshot(text: string): boolean {
    const game = decodeSnapshot(text);
    if (!game) {
      notice(SessionNotice.invalidSnapshot);
      return false;
    }
    clock.reset();
    commit(replaceGame(current.current, game, true));
    return true;
  }

  function exportSnapshot(): string {
    // Rendered state can trail the active clock by a tick.
    clock.synchronize();
    return encodeSnapshot(current.current.game);
  }

  function activate(index: number): void {
    clock.synchronize();
    commit(activateSession(current.current, index));
  }

  function resume(): void {
    clock.reset();
    commit({
      ...current.current,
      paused: false,
      feedback: '',
      loadNotice: '',
    });
  }

  return {
    session,
    newGame,
    restart,
    rename,
    loadBoard,
    loadSnapshot,
    exportSnapshot,
    activate,
    resume,
  };
}
import { createGame, isValidGameName, MOVES_MAX, ELAPSED_MAX_MS } from './game.ts';
import { parseBoardCode } from './deck.ts';
import {
  hasExactKeys,
  isJsonObject,
  isNonnegativeSafeInteger,
  isWithinBytes,
  parseJson,
} from './saved-format.ts';
import { readMatched, readSelection } from './snapshot-selection.ts';
import { SelectionKind } from './selection.ts';
import type { GameState } from './game.ts';

export const SNAPSHOT_VERSION = 1;
export const SNAPSHOT_MAX_BYTES = 65_536;
export const SNAPSHOT_KEYS = [
  'version',
  'boardCode',
  'matched',
  'selection',
  'moves',
  'elapsedMs',
  'started',
] as const;

export function encodeSnapshot(state: GameState): string {
  return JSON.stringify(
    {
      version: SNAPSHOT_VERSION,
      boardCode: state.boardCode,
      matched: [...state.matched].sort((left, right) => left - right),
      // Active time keeps its fractions in play. Export writes whole milliseconds, and rounding
      // pending time up keeps a mismatch at 1ms or more.
      selection:
        state.selection.kind === SelectionKind.mismatch
          ? { ...state.selection, remainingMs: Math.ceil(state.selection.remainingMs) }
          : state.selection,
      moves: state.moves,
      elapsedMs: Math.floor(state.elapsedMs),
      started: state.started,
      ...(state.name === '' ? {} : { name: state.name }),
    },
    null,
    2,
  );
}

export function decodeSnapshot(text: string): GameState | null {
  const value = isWithinBytes(text, SNAPSHOT_MAX_BYTES) ? parseJson(text) : undefined;
  if (!isJsonObject(value)) return null;
  const hasName = Object.hasOwn(value, 'name');
  if (
    !hasExactKeys(value, hasName ? [...SNAPSHOT_KEYS, 'name'] : SNAPSHOT_KEYS) ||
    value.version !== SNAPSHOT_VERSION
  )
    return null;
  const name = hasName ? value.name : '';
  if (!isValidGameName(name)) return null;
  if (typeof value.boardCode !== 'string' || !parseBoardCode(value.boardCode)) return null;
  if (
    !isNonnegativeSafeInteger(value.moves) ||
    value.moves > MOVES_MAX ||
    !isNonnegativeSafeInteger(value.elapsedMs) ||
    value.elapsedMs > ELAPSED_MAX_MS ||
    typeof value.started !== 'boolean'
  )
    return null;
  const initial = createGame(value.boardCode, name);
  const matched = readMatched(value.matched, initial);
  if (!matched) return null;
  const selection = readSelection(value.selection, initial, matched);
  if (!selection) return null;
  const state: GameState = {
    ...initial,
    matched,
    selection,
    moves: value.moves,
    elapsedMs: value.elapsedMs,
    started: value.started,
  };
  const minimumMoves = matched.length / 2 + (selection.kind === SelectionKind.mismatch ? 1 : 0);
  if (state.moves < minimumMoves) return null;
  if (
    !state.started &&
    (state.moves !== 0 ||
      state.elapsedMs !== 0 ||
      matched.length !== 0 ||
      selection.kind !== SelectionKind.closed)
  )
    return null;
  if (state.started && state.moves === 0 && selection.kind === SelectionKind.closed) return null;
  return state;
}

